"""Returns a list of dictionaries based on the column headers
    (the 0th line in the column headers)

    """
def get_dict_list(data_array: Any) -> object {
    key_list = data_array[0];
    dict_list = [];
    for (index, line) in enumerate(data_array[1:]) {
        params = {};
        for i in range(len(key_list)) {
            params[key_list[i]] = line[i];
        }
        dict_list.append(params);
    }
    return dict_list;
}

"""

    Helper function to return the equation of a line
    passing through any two points.

    :Parameters:

    x1: float
        X coordinate of first point
    y1: float
        Y coordinate of first point
    x2: float
        X coordinate of second point
    y2: float
        Y coordinate of second point

    :Returns:

    (slope, intercept) or (None, xposition) if the slope is infinite.

    """
def line_from_two_points(x1: Any, y1: Any, x2: Any, y2: Any) -> object {
    xdiff = x2 - x1;
    if (abs(xdiff) > 0.0) {
        ydiff = y2 - y1;
        slope = ydiff / xdiff;
        intercept = y1 - (slope * x1);
        return (slope, intercept);
    } else {
        return (None, x1);
    }
}

