    return (3-tuple): 3d vector
    """
def vect3_add(v1: Any, v2: Any) -> object {
    return ((v1[0] + v2[0]), (v1[1] + v2[1]), (v1[2] + v2[2]));
}

"""
    Extract all (and only) the path vars in a dictionary.

    :param d: a .paths.json data structure
    :return: all path var definitions without any special entries like '__ENV'
    """
def path_vars_in(d: Any) -> object {
    return [
        p
        for p in d.items()
        if (p[0] != '__ENV')
    ];
}

"""
Decodes html encoded emails
Pass a list of emails
Decodes email if starting characters are '&#'
Returns list of unencoded emails
"""
def decrypt(lst: list) -> object {
    while True {
        unencoded_emails = [];
        for string in lst {
            if (string[0:2] == '&#') {
                slices = int((len(string) / 6));
                count = 0;
                starting_pos = 0;
                decoded_email = '';
                while (count < slices) {
                    decoded_email = (
                        decoded_email
                        + chr(int(string[(starting_pos + 2):(starting_pos + 5)]))
                    );
                    count += 1;
                    starting_pos += 6;
                }
                unencoded_emails.append(decoded_email);
            } else {
                unencoded_emails.append(string);
            }
        }
        return unencoded_emails;
    }
}
